const scans = $('Get completed scans').all().map(i => i.json);
const sheetRaw = $('Extract Sentrixs').first().json.sheet;
const sheet = JSON.parse(sheetRaw);
const careSiteMapping = $('Get care_site_mapping').all().map(i => i.json);

const scanMap = {};
scans.forEach(scan => {
  scanMap[scan.sentrix_id] = scan;
});

const careSiteMap = {};
careSiteMapping.forEach(row => {
  careSiteMap[row.care_site_source_value] = row.care_site_ref;
});

const results = [];
sheet.forEach(row => {
  const scan = scanMap[row.Barkod];
  if (scan) {
    results.push({
      json: {
        scan_ref: scan.uniqueref,
        sentrix_id: scan.sentrix_id,
        chiptype_ref: scan.chiptype_ref,
        performing_caresite_ref: scan.care_site_ref,
        position: row.Pozisyon,
        sample_id: row['Örnek'],
        requesting_caresite_ref: careSiteMap[row.Kurum] || null
      }
    });
  }
});

return results.length > 0 ? results : [{ json: { action: 'none' } }];

const items = $input.all();
const prevItems = $('Merge SQL and Sheet').all();
const results = [];

items.forEach((item, index) => {
  try {
    const parsed = JSON.parse(item.json.stdout);
    const prev = prevItems[index].json;
    results.push({
      json: {
        scan_ref: prev.scan_ref,
        sentrix_id: prev.sentrix_id,
        chiptype_ref: prev.chiptype_ref,
        performing_caresite_ref: prev.performing_caresite_ref,
        requesting_caresite_ref: prev.requesting_caresite_ref,
        position: prev.position,
        sample_id: prev.sample_id,
        green_idat_path: parsed.green_idat_path,
        red_idat_path: parsed.red_idat_path,
        total_rescan_count: parsed.total_rescan_count,
        position_rescan_count: parsed.position_rescan_count,
        is_rescanned: parsed.is_rescanned
      }
    });
  } catch {
    // parse hatası, atla
  }
});

return results;

parameters.query:
SELECT uniqueref, rescan_count, scan_ref, position FROM idats 
WHERE scan_ref = {{ $json.scan_ref }} 
AND position = '{{ $json.position }}'

parameters.jsCode:
const checkResults = $('Check idat exists').all().map(i => i.json);
const parseResults = $('Parse').all().map(i => i.json);

const existingMap = {};
checkResults.forEach(r => {
  if (r.uniqueref) {
    existingMap[`${r.scan_ref}_${r.position}`] = r;
  }
});

const results = [];

parseResults.forEach(current => {
  const key = `${current.scan_ref}_${current.position}`;
  const dbRecord = existingMap[key];

  if (!dbRecord) {
    results.push({ json: { ...current, action: 'insert' } });
  } else if (parseInt(dbRecord.rescan_count) !== current.position_rescan_count) {
    results.push({ json: { ...current, action: 'update', idat_ref: dbRecord.uniqueref } });
  } else {
    results.push({ json: { ...current, action: 'none' } });
  }
});

return results;

const sheet = $input.all().map(i => i.json);
const barkodlar = [...new Set(sheet.map(row => `'${row.Barkod}'`))].join(',');
const kurumlar = [...new Set(sheet.map(row => row.Kurum).filter(Boolean).map(k => `'${k}'`))].join(',');
return [{ json: { barkodlar, kurumlar, sheet: JSON.stringify(sheet) } }];

let sentrixIdsRaw;
try {
  sentrixIdsRaw = $('When Executed by Another Workflow').first().json.sentrix_ids;
} catch {
  sentrixIdsRaw = $('Collect Missing IDs').first().json.sentrix_ids;
}
const sentrixIds = new Set(sentrixIdsRaw.map(String));

// Sheet 1 Part 1 (header burada)
const data1 = JSON.parse($('Fetch Aktif Part1').first().json.stdout);
const headers1 = data1.values[0];
const rows1 = data1.values.slice(1);
// Sheet 1 Part 2 (header yok)
let rows1p2 = [];
try {
  const raw = $('Fetch Aktif Part2').first().json.stdout;
  if (raw && raw.trim()) {
    const parsed = JSON.parse(raw);
    rows1p2 = parsed.values || [];
  }
} catch {}
// Sheet 2 (kendi headerı var)
const data2 = JSON.parse($('Fetch Sayfa1').first().json.stdout);
const headers2 = data2.values[0];
const rows2 = data2.values.slice(1);
// Objelere çevir
const sheet1Rows = [...rows1, ...rows1p2].map(row =>
  Object.fromEntries(headers1.map((h, i) => [h, row[i] ?? '']))
);
const sheet2Rows = rows2.map(row =>
  Object.fromEntries(headers2.map((h, i) => [h, row[i] ?? '']))
);
// Sadece gelen sentrix_id'lerle eşleşen satırlar
const allRows = [...sheet1Rows, ...sheet2Rows];
const filtered = allRows.filter(row => sentrixIds.has(String(row.Barkod)));
if (filtered.length === 0) return [];
return filtered.map(row => ({ json: row }));

const items = $input.all().map(i => i.json.sentrix_id).filter(Boolean);
if (items.length === 0) return [];
return [{ json: { sentrix_ids: items } }];

